-- interop_transfer: A two-phase transfer to or from another participant
CREATE TABLE interop_transfer (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  interop_switch_id            uuid NOT NULL REFERENCES interop_switch(id),
  interop_quote_id             uuid REFERENCES interop_quote(id),
  transfer_id                  varchar(64) NOT NULL,
  direction                    varchar(40) NOT NULL CHECK (direction IN ('OUTBOUND', 'INBOUND')),
  payer_wallet_id              uuid,
  payee_wallet_id              uuid,
  counterparty_fsp_id          varchar(64) NOT NULL,
  counterparty_party_id        varchar(64),
  amount                       numeric(28,8) NOT NULL,
  currency                     char(3) NOT NULL,
  fee_amount                   numeric(28,8),
  ilp_condition                varchar(128),
  status                       varchar(40) NOT NULL DEFAULT 'QUOTE_REQUESTED' CHECK (status IN ('QUOTE_REQUESTED', 'QUOTED', 'RESERVED', 'COMMITTED', 'ABORTED', 'FAILED', 'EXPIRED')),
  wallet_transaction_id        uuid,
  hold_id                      uuid,
  fulfilment                   varchar(128),
  expires_at                   timestamptz,
  completed_at                 timestamptz,
  error_code                   varchar(32),
  error_description            varchar(255),
  idempotency_key              varchar(128) NOT NULL,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_interop_transfer_transfer_id UNIQUE (tenant_id, transfer_id),
  CONSTRAINT uq_interop_transfer_1 UNIQUE (tenant_id, idempotency_key)
);
